private fun sym(name: String, d: String, mirror: Boolean = false): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f, autoMirror = mirror)
        .addGroup(translationY = 960f)
        .addPath(addPathNodes(d), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()

class Symbol(val outline: ImageVector, val fill: ImageVector)

private fun pair(name: String, mirror: Boolean, o: String, f: String) = Symbol(sym(name, o, mirror), sym(name + "Fill", f, mirror))

